"use client";
import VendorShell from "../../../components/VendorShell";
import { useEffect, useMemo, useState } from 'react';
import { api, patch, post } from "../../../lib/api";

type Item={id:string;groupId:string;name:string;additionalPrice:number;isAvailable:boolean;stockQuantity:number|null;lowStockThreshold:number|null;displayOrder:number};
type Group={id:string;productId:string;name:string;isRequired:boolean;minSelections:number;maxSelections:number;isActive:boolean;availabilityStartTime:string|null;availabilityEndTime:string|null;displayOrder:number;items:Item[];product:{id:string;name:string;priceAmount:number;isAvailable:boolean}};
type Product={id:string;name:string;priceAmount:number};
const money=(n:number)=>`₦${(n/100).toLocaleString("en-NG",{maximumFractionDigits:2})}`;
export default function Options(){const[g,setG]=useState<Group[]>([]),[p,setP]=useState<Product[]>([]),[q,setQ]=useState(""),[pf,setPf]=useState("all"),[loading,setLoading]=useState(true),[error,setError]=useState(""),[success,setSuccess]=useState(""),[groupModal,setGroupModal]=useState(false),[itemModal,setItemModal]=useState(false),[editGroup,setEditGroup]=useState<Group|null>(null),[editItem,setEditItem]=useState<Item|null>(null),[groupId,setGroupId]=useState(""),[pid,setPid]=useState(""),[name,setName]=useState(""),[required,setRequired]=useState(false),[min,setMin]=useState("0"),[max,setMax]=useState("1"),[start,setStart]=useState(""),[end,setEnd]=useState(""),[price,setPrice]=useState("0"),[available,setAvailable]=useState(true),[stock,setStock]=useState(""),[threshold,setThreshold]=useState(""),[saving,setSaving]=useState(false);
async function load(){try{setLoading(true);setError("");const[a,b]=await Promise.all([api<Group[]>("/api/vendor/options"),api<Product[]>("/api/vendor/products")]);setG(Array.isArray(a)?a:[]);setP(Array.isArray(b)?b:[])}catch(e:any){setError(e?.message||"Failed to load options.")}finally{setLoading(false)}}useEffect(()=>{load()},[]);
const rows=useMemo(()=>g.filter(x=>(!q||`${x.name} ${x.product.name} ${x.items.map(i=>i.name).join(" ")}`.toLowerCase().includes(q.toLowerCase()))&&(pf==="all"||x.productId===pf)),[g,q,pf]);
function resetGroup(){setEditGroup(null);setPid(p[0]?.id||"");setName("");setRequired(false);setMin("0");setMax("1");setStart("");setEnd("");setGroupModal(true)}
function openGroup(x:Group){setEditGroup(x);setPid(x.productId);setName(x.name);setRequired(x.isRequired);setMin(String(x.minSelections));setMax(String(x.maxSelections));setStart(x.availabilityStartTime||"");setEnd(x.availabilityEndTime||"");setGroupModal(true)}
function openItem(x:Item){setEditItem(x);setGroupId(x.groupId);setName(x.name);setPrice(String(x.additionalPrice/100));setAvailable(x.isAvailable);setStock(x.stockQuantity==null?"":String(x.stockQuantity));setThreshold(x.lowStockThreshold==null?"":String(x.lowStockThreshold));setItemModal(true)}
function newItem(id:string){setEditItem(null);setGroupId(id);setName("");setPrice("0");setAvailable(true);setStock("");setThreshold("");setItemModal(true)}
async function saveGroup(){try{setSaving(true);setError("");const mn=Number(min),mx=Number(max);if(!pid&&!editGroup)throw Error("Select a product.");if(!name.trim())throw Error("Option group name is required.");if(!Number.isInteger(mn)||!Number.isInteger(mx)||mn<0||mx<1||mn>mx)throw Error("Minimum selections cannot exceed maximum selections.");const body={name:name.trim(),isRequired:required,minSelections:mn,maxSelections:mx,availabilityStartTime:start||null,availabilityEndTime:end||null};if(editGroup){await patch(`/api/vendor/options/groups/${editGroup.id}`,body);setSuccess("Option group updated.")}else{await post(`/api/vendor/options/products/${pid}/groups`,body);setSuccess("Option group created.")}setGroupModal(false);await load()}catch(e:any){setError(e?.message||"Failed to save option group.")}finally{setSaving(false)}}
async function saveItem(){try{setSaving(true);setError("");const pr=Number(price),st=stock===""?null:Number(stock),th=threshold===""?null:Number(threshold);if(!groupId)throw Error("Select an option group.");if(!name.trim())throw Error("Option item name is required.");if(!Number.isFinite(pr)||pr<0)throw Error("Enter a valid additional price.");if(st!==null&&(!Number.isInteger(st)||st<0))throw Error("Stock must be a whole number of 0 or more.");if(th!==null&&(!Number.isInteger(th)||th<0))throw Error("Low-stock threshold must be 0 or more.");const body={name:name.trim(),additionalPrice:Math.round(pr*100),isAvailable:available,stockQuantity:st,lowStockThreshold:th};if(editItem){await patch(`/api/vendor/options/items/${editItem.id}`,body);setSuccess("Option item updated.")}else{await post(`/api/vendor/options/groups/${groupId}/items`,body);setSuccess("Option item created.")}setItemModal(false);await load()}catch(e:any){setError(e?.message||"Failed to save option item.")}finally{setSaving(false)}}
async function toggleGroup(x:Group){try{await post(`/api/vendor/options/groups/${x.id}/${x.isActive?"deactivate":"activate"}`);await load()}catch(e:any){setError(e?.message||"Failed to change group status.")}}
async function toggleItem(x:Item){try{await post(`/api/vendor/options/items/${x.id}/${x.isAvailable?"deactivate":"activate"}`);await load()}catch(e:any){setError(e?.message||"Failed to change item status.")}}
async function del(x:Item){if(!confirm(`Delete “${x.name}”?`))return;try{await post(`/api/vendor/options/items/${x.id}/delete`);setSuccess("Option item deleted.");await load()}catch(e:any){setError(e?.message||"Failed to delete option item.")}}
async function moveGroup(x:Group,d:number){const a=g.filter(y=>y.productId===x.productId).sort((m,n)=>m.displayOrder-n.displayOrder),i=a.findIndex(y=>y.id===x.id),j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];try{await post(`/api/vendor/options/products/${x.productId}/groups/reorder`,{groupIds:a.map(y=>y.id)});await load()}catch(e:any){setError(e?.message||"Failed to reorder groups.")}}
async function moveItem(x:Item,d:number){const group=g.find(y=>y.id===x.groupId);if(!group)return;const a=[...group.items].sort((m,n)=>m.displayOrder-n.displayOrder),i=a.findIndex(y=>y.id===x.id),j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];try{await post(`/api/vendor/options/groups/${x.groupId}/items/reorder`,{itemIds:a.map(y=>y.id)});await load()}catch(e:any){setError(e?.message||"Failed to reorder items.")}}
return <VendorShell><main className="page-content"><div className="page-heading"><div><div className="eyebrow">CATALOG</div><h1>Options &amp; Add-ons</h1><p className="muted">Build flexible customization groups for food, groceries, gadgets, fashion, and any other product.</p></div><button className="btn primary" onClick={resetGroup}>＋ Add option group</button></div>{error&&<div className="alert error">{error}</div>}{success&&<div className="alert success">{success}</div>}<div className="metric-grid"><div className="metric-card"><span>Option groups</span><strong>{g.length}</strong></div><div className="metric-card"><span>Active groups</span><strong>{g.filter(x=>x.isActive).length}</strong></div><div className="metric-card"><span>Option items</span><strong>{g.reduce((n,x)=>n+x.items.length,0)}</strong></div><div className="metric-card"><span>Unavailable items</span><strong>{g.reduce((n,x)=>n+x.items.filter(i=>!i.isAvailable).length,0)}</strong></div></div><section className="content-card"><div className="toolbar"><input className="input search-input" value={q} onChange={e=>setQ(e.target.value)} placeholder="Search groups, items or products..."/><select className="input filter-select" value={pf} onChange={e=>setPf(e.target.value)}><option value="all">All products</option>{p.filter(x=>g.some(y=>y.productId===x.id)).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select><button className="btn secondary" onClick={load}>Refresh</button></div>{loading?<div className="state-panel"><h3>Loading options…</h3></div>:!rows.length?<div className="state-panel"><div className="state-icon">⊞</div><h3>{g.length?"No options match your filters":"No option groups yet"}</h3><p className="muted">Create a group such as Protein, Extras, Color, Size, Storage or Accessories.</p>{!g.length&&<button className="btn primary" onClick={resetGroup}>Create first group</button>}</div>:<div className="option-list">{rows.map(x=><article className="option-group-card" key={x.id}><div className="option-group-head"><div><div className="table-secondary">{x.product.name}</div><h3>{x.name}</h3><div className="option-rule">{x.isRequired?"Required":"Optional"} · choose {x.minSelections}–{x.maxSelections}</div>{(x.availabilityStartTime||x.availabilityEndTime)&&<div className="table-secondary">Available {x.availabilityStartTime||"any time"} – {x.availabilityEndTime||"any time"}</div>}</div><div className="row-actions"><span className={`status-badge ${x.isActive?"status-active":"status-danger"}`}>{x.isActive?"Active":"Inactive"}</span><button className="text-button" onClick={()=>openGroup(x)}>Edit</button><button className="text-button" onClick={()=>toggleGroup(x)}>{x.isActive?"Deactivate":"Activate"}</button><button className="icon-button" onClick={()=>moveGroup(x,-1)}>↑</button><button className="icon-button" onClick={()=>moveGroup(x,1)}>↓</button></div></div><div className="option-items">{x.items.length?x.items.map(i=>{const low=i.stockQuantity!==null&&i.lowStockThreshold!==null&&i.stockQuantity<=i.lowStockThreshold;return <div className="option-item-row" key={i.id}><div><strong>{i.name}</strong><div className="table-secondary">{i.additionalPrice?`+${money(i.additionalPrice)}`:"No extra charge"}{i.stockQuantity!==null?` · ${i.stockQuantity} stock`:" · Unlimited stock"}</div></div><div className="row-actions"><span className={`status-badge ${!i.isAvailable?"status-danger":low?"status-warning":"status-active"}`}>{!i.isAvailable?"Unavailable":low?"Low stock":"Available"}</span><button className="text-button" onClick={()=>openItem(i)}>Edit</button><button className="text-button" onClick={()=>toggleItem(i)}>{i.isAvailable?"Disable":"Enable"}</button><button className="text-button danger-text" onClick={()=>del(i)}>Delete</button><button className="icon-button" onClick={()=>moveItem(i,-1)}>↑</button><button className="icon-button" onClick={()=>moveItem(i,1)}>↓</button></div></div>}):<div className="empty-inline">No option items yet.</div>}<button className="btn secondary add-item" onClick={()=>newItem(x.id)}>＋ Add option item</button></div></article>)}</div>}</section><div className="info-banner"><strong>How ROZZI uses this</strong><span>Option groups define the customer's choice rules. Option items carry the extra price, availability and optional stock. This is intentionally category-agnostic.</span></div>{groupModal&&<div className="modal-backdrop" onMouseDown={e=>e.currentTarget===e.target&&setGroupModal(false)}><section className="small-modal"><button className="drawer-close modal-x" onClick={()=>setGroupModal(false)}>×</button><div className="eyebrow">{editGroup?"EDIT GROUP":"NEW GROUP"}</div><h2>{editGroup?"Edit option group":"Create option group"}</h2><p className="muted">Examples: Protein, Extras, Color, Storage, Accessories.</p>{!editGroup&&<label>Product<select className="input" value={pid} onChange={e=>setPid(e.target.value)}><option value="">Select product</option>{p.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label>}<label>Group name<input className="input" value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Protein"/></label><label className="check-row"><input type="checkbox" checked={required} onChange={e=>{setRequired(e.target.checked);if(e.target.checked&&min==="0")setMin("1")}}/> Required selection</label><div className="form-grid"><label>Minimum selections<input className="input" type="number" min="0" value={min} onChange={e=>setMin(e.target.value)}/></label><label>Maximum selections<input className="input" type="number" min="1" value={max} onChange={e=>setMax(e.target.value)}/></label></div><div className="form-grid"><label>Available from <span className="field-optional">Optional</span><input className="input" type="time" value={start} onChange={e=>setStart(e.target.value)}/></label><label>Available until <span className="field-optional">Optional</span><input className="input" type="time" value={end} onChange={e=>setEnd(e.target.value)}/></label></div><div className="modal-actions"><button className="btn secondary" onClick={()=>setGroupModal(false)}>Cancel</button><button className="btn primary" disabled={saving} onClick={saveGroup}>{saving?"Saving…":editGroup?"Save changes":"Create group"}</button></div></section></div>}{itemModal&&<div className="modal-backdrop" onMouseDown={e=>e.currentTarget===e.target&&setItemModal(false)}><section className="small-modal"><button className="drawer-close modal-x" onClick={()=>setItemModal(false)}>×</button><div className="eyebrow">{editItem?"EDIT ITEM":"NEW ITEM"}</div><h2>{editItem?"Edit option item":"Add option item"}</h2><p className="muted">Set the customer-facing choice and its additional charge.</p><label>Option name<input className="input" value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Chicken"/></label><label>Additional price<input className="input" type="number" min="0" step="0.01" value={price} onChange={e=>setPrice(e.target.value)} placeholder="0"/></label><div className="form-grid"><label>Stock quantity <span className="field-optional">Blank = unlimited</span><input className="input" type="number" min="0" step="1" value={stock} onChange={e=>setStock(e.target.value)}/></label><label>Low-stock threshold <span className="field-optional">Optional</span><input className="input" type="number" min="0" step="1" value={threshold} onChange={e=>setThreshold(e.target.value)}/></label></div><label className="check-row"><input type="checkbox" checked={available} onChange={e=>setAvailable(e.target.checked)}/> Available to customers</label><div className="modal-actions"><button className="btn secondary" onClick={()=>setItemModal(false)}>Cancel</button><button className="btn primary" disabled={saving} onClick={saveItem}>{saving?"Saving…":editItem?"Save changes":"Create item"}</button></div></section></div>}</main></VendorShell>}
